'use strict';

const assert = require('node:assert');
const { it } = require('node:test');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { mkdtempSync, rmSync } = require('node:fs');
const { tmpdir } = require('node:os');

// AI: below section was generated by an AI

it('tracks known synthetic tempos through the production spectrum interface', () => {
  // The test compiles the firmware-owned header directly, so the synthetic
  // spectra exercise the same fixed-memory estimator that runs on the pole.
  const repository = path.resolve(__dirname, '..');
  const temporary = mkdtempSync(path.join(tmpdir(), 'wled-tempo-test-'));
  const executable = path.join(temporary, 'tempo-tracker-test');
  try {
    const compile = spawnSync(
      process.env.CXX || 'c++',
      ['-std=c++11', '-O2', '-Wall', '-Wextra', '-Werror',
        path.join(__dirname, 'tempo-tracker-test.cpp'), '-o', executable],
      { cwd: repository, encoding: 'utf8' },
    );
    assert.strictEqual(compile.status, 0, compile.stderr || compile.stdout);

    const run = spawnSync(executable, [], { cwd: repository, encoding: 'utf8' });
    assert.strictEqual(run.status, 0, run.stderr || run.stdout);
    assert.match(run.stdout, /tempo tracker scenarios passed/);
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

